from audit_edit import replace

def a(c,n):return f'appendices/app{c}*/sections/sec-{c.lower()}-{n}-*.xml'
replace(a('A',3),'There are two common traps:', 'The following two inequalities illustrate common traps; they hold in general rather than for every possible choice of inputs:', 'Clarify that failed identities may agree for special inputs')
replace(a('A',3),'a^{m/n}=\\left(\\sqrt[n]{a}\\right)^m.',r'a^{m/n}=\left(\sqrt[n]{a}\right)^m.','placeholder') if False else None
replace(a('A',3),'A fractional exponent means a root:',r'For an integer <m>n&gt;0</m>, a fractional exponent means a root:','State a positive root index')
replace(a('A',3),'when the root is defined.  More generally,',r'when the root is defined. For a negative base, write a rational exponent <m>m/n</m> in lowest terms with <m>n&gt;0</m>; a real value requires <m>n</m> odd. If <m>m&lt;0</m>, also exclude a zero base. More generally,','Define rational powers of negative bases consistently and exclude reciprocal zero')
replace(a('B',3),'A vertical parabola has vertex form', r'A vertical parabola, with <m>a\ne0</m>, has vertex form','Exclude the degenerate constant graph')
replace(a('B',3),'For a vertical parabola with vertex <m>(h,k)</m>,',r'For a vertical parabola with vertex <m>(h,k)</m> and <m>p\ne0</m>,','Exclude a degenerate focus-directrix parameter')
replace(a('B',3),'An ellipse is an oval.  Its standard equation is','An ellipse is an oval. With <m>a,b&gt;0</m>, its standard equation is','Semi-axis lengths are positive')
replace(a('B',3),'A hyperbola has two branches and two asymptotes.', 'A hyperbola has two branches and two asymptotes. In its standard forms below, <m>a,b&gt;0</m>.','Ensure nondegenerate hyperbola parameters')
replace(a('B',3),'When no <m>xy</m>-term appears, the squared terms give a quick first test.', 'When no <m>xy</m>-term appears, the squared terms give a quick first test for a nondegenerate conic. Complete the square and check the constants: degenerate equations can instead describe a point, one or two lines, or the empty set.','Squared-term signs alone do not exclude degenerate conics')
replace(a('C',1),r'If a circle has radius <m>r</m>, and a central angle <m>\theta</m> cuts off an arc of length <m>s</m>, then',r'If a circle has radius <m>r&gt;0</m>, and a nonnegative central angle <m>\theta</m> cuts off an arc of length <m>s</m>, then','An ordinary arc length cannot be negative')
replace(a('C',1),r'Move counterclockwise along the circle through an arc of length <m>\theta</m>.',r'Move through signed angle <m>\theta</m>, counterclockwise for positive <m>\theta</m> and clockwise for negative <m>\theta</m>. The distance traveled along the circle is <m>|\theta|</m>.','Give a consistent unit-circle definition for negative angles')
replace(a('C',3),'A common mistake is to distribute sine or cosine over addition.  That is not correct:', 'A common mistake is to distribute sine or cosine over addition. The following inequalities hold in general; the two expressions can agree at special inputs:', 'Distinguish a false general identity from a universal inequality')
replace(a('C',4),'Use a right triangle with opposite side <m>x</m>, adjacent side <m>1</m>, and hypotenuse',r'For <m>x&gt;0</m>, use a right triangle with opposite side <m>x</m>, adjacent side <m>1</m>, and hypotenuse','A negative number cannot be a triangle side length')
replace(a('C',4),r'Therefore <p><me>\sin(\arctan x)=\frac{x}{\sqrt{x^2+1}}.</me></p>',r'Therefore <p><me>\sin(\arctan x)=\frac{x}{\sqrt{x^2+1}}.</me></p><p>At <m>x=0</m>, both sides are zero. For <m>x&lt;0</m>, use the oddness of sine and arctangent to obtain the same formula.</p>','Extend the triangle derivation correctly to zero and negative inputs')
replace(a('C',5),r'If we had divided by <m>\cos x</m>, we would have lost both cases where <m>\cos x=0</m>.',r'Blindly dividing by <m>\cos x</m> would leave <m>\sin x=1</m> and miss the solution <m>x=3\pi/2</m>. Such division is not valid at either solution of the original equation.','The blindly divided equation still retains one of the two solutions')
replace(a('D',5),'enough for tangent behavior at a point','local control of function values at a point','Continuity alone does not imply a tangent exists')
replace(a('D',5),'compare the two nearby numbers',r'for <m>n\ge2</m>, compare the two nearby numbers','The n equals one input is outside the stated open interval')
replace(a('D',6),r'Use the pairs <p><me>x_n=\frac1n, \qquad y_n=\frac1{n+1}.</me></p>',r'For <m>n\ge2</m>, use the pairs <p><me>x_n=\frac1n, \qquad y_n=\frac1{n+1}.</me></p>','Keep all witness pairs within the open interval')
replace(a('E',3),'Both represent the same number, but they serve different purposes.', 'The decimal approximates the exact number; the two forms serve different purposes.','A finite rounded decimal is not equal to the exact irrational value')
replace(a('E',5),'A Taylor polynomial is a sequence of polynomial approximations:', 'Taylor polynomials form a sequence of polynomial approximations:','A single polynomial is not a sequence')
replace(a('F',2),'The two are connected by the Fundamental Theorem of Calculus.', 'The two are connected by the Fundamental Theorem of Calculus. Apply the tables on intervals where every expression is defined. For definite integral rules, assume the integrands are continuous; for substitution assume <m>g</m> has a continuous derivative, and for integration by parts assume <m>u</m> and <m>v</m> have continuous derivatives. Antiderivative constants are chosen separately on disconnected domain intervals.','Attach sufficient hypotheses and domain conventions to the reference tables')
replace(a('F',3),'The Taylor polynomial of degree <m>N</m> for <m>f</m> centered at <m>a</m> is', 'The Taylor polynomial of order <m>N</m>, with degree at most <m>N</m>, for <m>f</m> centered at <m>a</m> is','Taylor order need not equal polynomial degree')
replace(a('F',3),'under the usual differentiability hypotheses,', 'when <m>f</m> has continuous derivatives through order <m>N+1</m> on an interval containing <m>a</m> and <m>x</m>,','State the actual remainder hypothesis in the quick reference')
replace(a('F',3),'A series centered at <m>a</m> is obtained by replacing <m>x</m> with <m>x-a</m>.', 'A series centered at <m>a</m> uses powers of <m>x-a</m>. To represent the same function at a new center, rewrite the function or recompute its Taylor coefficients; merely replacing <m>x</m> by <m>x-a</m> would shift the function itself.','Changing the center requires new coefficients rather than a simple variable substitution')
replace(a('F',3),r'Also, <p><me>\frac1{1-x}',r'Also, for <m>a\ne1</m>, <p><me>\frac1{1-x}','The shifted geometric formula divides by one minus its center')
replace(a('F',4),r'Diverges if <m>|r|\ge1</m>.',r'Diverges if <m>|r|\ge1</m> and <m>a\ne0</m>; for <m>a=0</m> the series is zero.','The zero geometric series converges for every ratio')
replace(a('F',4),'Same hypotheses as the integral test.', 'Same hypotheses as the integral test, with a convergent series and <m>N</m> in the region where <m>f</m> is decreasing.','The tail estimate assumes a finite sum and sufficiently late monotonicity')
replace(a('F',4),r'Compute <m>L=\lim_{n\to\infty}\left|\frac{a_{n+1}}{a_n}\right|</m>.',r'Assume <m>a_n\ne0</m> eventually and compute <m>L=\lim_{n\to\infty}\left|\frac{a_{n+1}}{a_n}\right|</m>.','A ratio test requires defined ratios')
replace(a('F',5),r'Let <p><me>\Delta x',r'Let <m>a&lt;b</m> and let <m>n</m> be a positive integer. Set <p><me>\Delta x','Quadrature widths and error bounds require positive interval length and subdivision count')
